   420                  ssize_t slen;
   421
   422                  FR_PROTO_HEX_DUMP(p, end - p, "fr_dns_decode - %s %d/%d", attr->name, i, count);
   423
   424                  if (p >= end) {
   425                          FR_PROTO_TRACE("%s overflows packet at %d", attr->name, i);
   426                          return -(p - packet);
   427                  }
   428
   429                  slen = fr_struct_from_network(ctx, cursor, attr, p, end - p, true,
   430                                                packet_ctx, decode_value_trampoline, NULL);
   850                          if (dns_label_compress(buf, buf, where, NULL, where, &data)) {
   851                                  FR_PROTO_TRACE("Compressed single label %s to %zu bytes",
   852                                                 value->vb_strvalue, data - where);
   853                          } else {
   854                                  FR_PROTO_TRACE("Did not compress single label");
   855                          }
   856                  }
   857          } else {
   858                  FR_PROTO_TRACE("Not compressing label");
   859          }
   860
   861          fr_assert(data > where);
   862          return data - where;
   863  }
