   117  static ssize_t decode_value(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_t const *dict,
   118                              fr_dict_attr_t const *parent,
   119                              uint8_t const *data, size_t const data_len, void *decode_ctx)
   120  {
   120  {
   121          ssize_t                 slen;
   122          fr_pair_t               *vp;
   123          uint8_t                 prefix_len;
   124
   125          FR_PROTO_HEX_DUMP(data, data_len, "decode_value");
   126
   127          switch (parent->type) {
   128          /*
   129           *      Address MAY be shorter than 16 bytes.
   130           */
   131          case FR_TYPE_IPV6_PREFIX:
   132                  if ((data_len == 0) || (data_len > (1 + sizeof(vp->vp_ipv6addr)))) {
   133                  raw:
   134                          return decode_raw(ctx, cursor, dict, parent, data, data_len, decode_ctx);
   135
   136                  };
   137
   138                  /*
   139                   *      Structs used fixed length fields
   140                   */
   141                  if (parent->parent->type == FR_TYPE_STRUCT) {
   142                          if (data_len != (1 + sizeof(vp->vp_ipv6addr))) goto raw;
   143
   144                          vp = fr_pair_afrom_da(ctx, parent);
   145                          if (!vp) return PAIR_DECODE_OOM;
   146
   147                          vp->vp_ip.af = AF_INET6;
   148                          vp->vp_ip.scope_id = 0;
   149                          vp->vp_ip.prefix = data[0];
   150                          memcpy(&vp->vp_ipv6addr, data + 1, data_len - 1);
   151                          break;
   152                  }
   153
   154                  /*
   155                   *      No address, the prefix length MUST be zero.
   156                   */
   157                  if (data_len == 1) {
   158                          if (data[0] != 0) goto raw;
   159
   160                          vp = fr_pair_afrom_da(ctx, parent);
   161                          if (!vp) return PAIR_DECODE_OOM;
   162
   163                          vp->vp_ip.af = AF_INET6;
   164                          vp->vp_ip.scope_id = 0;
   165                          vp->vp_ip.prefix = 0;
   166                          memset(&vp->vp_ipv6addr, 0, sizeof(vp->vp_ipv6addr));
   167                          break;
   168                  }
   169
   170                  prefix_len = data[0];
   171
   172                  /*
   173                   *      If we have a /64 prefix but only 7 bytes of
   174                   *      address, that's an error.
   175                   */
   176                  if (fr_bytes_from_bits(prefix_len) > (data_len - 1)) goto raw;
   177
   178                  vp = fr_pair_afrom_da(ctx, parent);
   179                  if (!vp) return PAIR_DECODE_OOM;
   180
   181                  vp->vp_ip.af = AF_INET6;
   182                  vp->vp_ip.scope_id = 0;
   183                  vp->vp_ip.prefix = prefix_len;
   184                  memset(&vp->vp_ipv6addr, 0, sizeof(vp->vp_ipv6addr));
   185                  memcpy(&vp->vp_ipv6addr, data + 1, data_len - 1);
   186                  break;
   187
   188          /*
   189           *      A bool is encoded as an empty option if it's
   190           *      true.  A bool is omitted entirely if it's
   191           *      false.
   192           */
   193          case FR_TYPE_BOOL:
   194                  if (data_len != 0) goto raw;
   195                  vp = fr_pair_afrom_da(ctx, parent);
   196                  if (!vp) return PAIR_DECODE_OOM;
   197                  vp->vp_bool = true;
   198                  break;
   199
   200          case FR_TYPE_STRUCT:
   201                  slen = fr_struct_from_network(ctx, cursor, parent, data, data_len, true,
   202                                                decode_ctx, decode_value_trampoline, NULL);
   203                  if (slen < 0) return slen;
   204                  return data_len;
   205
   206          case FR_TYPE_GROUP:
   207                  return PAIR_DECODE_FATAL_ERROR; /* not supported */
   208
   209  #if 0
   210          {
   211                  fr_dcursor_t child_cursor;
   212                  fr_pair_list_t head;
   213                  fr_pair_list_init(&head);
   214
   215                  vp = fr_pair_afrom_da(ctx, parent);
   216                  if (!vp) return PAIR_DECODE_OOM;
   217
   218                  /*
   219                   *      Child VPs go into the child group, not in the
   220                   *      main parent list.  We start decoding
   221                   *      attributes from the dictionary root, not from
   222                   *      this parent.  We also don't decode an option
   223                   *      header, as we're just decoding the values
   224                   *      here.
   225                   */
   226                  fr_dcursor_init(&child_cursor, &head);
   227                  slen = decode_tlvs(vp, &child_cursor, dict, fr_dict_root(dict_dns), data, data_len, decode_ctx, false);
   228                  if (slen < 0) {
   229                          talloc_free(vp);
   230                          goto raw;
   231                  }
   232                  fr_pair_list_append(&vp->vp_group, &head);
   233                  break;
   234          }
   235  #endif
   236
   237          default:
   238                  vp = fr_pair_afrom_da(ctx, parent);
   239                  if (!vp) return PAIR_DECODE_OOM;
   240
   241                  if (fr_value_box_from_network(vp, &vp->data, vp->da->type, vp->da,
   242                                                &FR_DBUFF_TMP(data, data_len), data_len, true) < 0) {
   243                          FR_PROTO_TRACE("failed decoding?");
   244                          talloc_free(vp);
   245                          goto raw;
   246                  }
   247                  break;
   248          }
   249
   250          vp->type = VT_DATA;
   251          vp->vp_tainted = true;
   252          fr_dcursor_append(cursor, vp);
   253          return data_len;
   254  }
