   257  static ssize_t decode_array(TALLOC_CTX *ctx, fr_dcursor_t *cursor, fr_dict_t const *dict,
   258                              fr_dict_attr_t const *parent,
   259                              uint8_t const *data, size_t const data_len, void *decode_ctx)
   260  {
   261          uint8_t const           *p = data, *end = p + data_len;
   262          ssize_t                 slen;
   263          size_t                  element_len;
   264
   265          FR_PROTO_HEX_DUMP(data, data_len, "decode_array");
   266
   267          if (!fr_cond_assert_msg(parent->flags.array,
   268                                  "%s: Internal sanity check failed, attribute \"%s\" does not have array bit set",
   269                                  __FUNCTION__, parent->name)) return PAIR_DECODE_FATAL_ERROR;
   270
   271  #if 0
   272          /*
   273           *      Fixed-size fields get decoded with a simple decoder.
   274           */
   275          element_len = fr_dns_attr_sizes[parent->type][0];
   276          if (element_len > 0) {
   277                  while (p < end) {
   278                          /*
   279                           *      Not enough room for one more element,
   280                           *      decode the last bit as raw data.
   281                           */
   282                          if ((size_t) (end - p) < element_len) {
   283                                  slen = decode_raw(ctx, cursor, dict, parent, p, end - p , decode_ctx);
   284                                  if (slen < 0) return slen;
   285                                  break;
   286                          }
   287
   288                          slen = decode_value(ctx, cursor, dict, parent, p, element_len, decode_ctx);
   289                          if (slen < 0) return slen;
   290                          if (!fr_cond_assert((size_t) slen == element_len)) return -(p - data);
   291
   292                          p += slen;
   293                  }
   294
   295                  /*
   296                   *      We MUST have decoded the entire input.  If
   297                   *      not, we ignore the extra bits.
   298                   */
   299                  return data_len;
   300          }
   301  #endif
   302
   303          /*
   304           *      If the data is variable length i.e. strings or octets
   305           *      there is a length field before each element.
   306           *
   307           *   +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-...-+-+-+-+-+-+-+
   308           *   |       text-len                |        String                 |
   309           *   +-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-+-...-+-+-+-+-+-+-+
   310           */
   311          while (p < end) {
   312                  if ((end - p) < 2) {
   313                  raw:
   314                          slen = decode_raw(ctx, cursor, dict, parent, p, end - p , decode_ctx);
   315                          if (slen < 0) return slen;
   316                          break;
   317                  }
   318
   319                  element_len = fr_net_to_uint16(p);
   320                  if ((p + 2 + element_len) > end) {
   321                          goto raw;
   322                  }
   323
   324                  p += 2;
   325                  slen = decode_value(ctx, cursor, dict, parent, p, element_len, decode_ctx);
   326                  if (slen < 0) return slen;
   327                  p += slen;
   328          }
   329
   330          return data_len;
   430                                                packet_ctx, decode_value_trampoline, NULL);
   431                  if (slen < 0) return slen;
   432                  p += slen;
   433          }
   434
   435          return p - packet;
   436  }
