   489  /** Decode DNS RR
   490   *
   491   * @param[in] ctx context       to alloc new attributes in.
   492   * @param[in,out] cursor        Where to write the decoded options.
   493   * @param[in] dict              to lookup attributes in.
   494   * @param[in] data              to parse.
   495   * @param[in] data_len          of data to parse.
   496   * @param[in] decode_ctx        Unused.
   497   */
   498  static ssize_t fr_dns_decode_rr(TALLOC_CTX *ctx, fr_dcursor_t *cursor,
   499                                  UNUSED fr_dict_t const *dict, uint8_t const *data, size_t data_len, void *decode_ctx)
   500  {
   501          ssize_t                 slen;
   502          fr_dns_ctx_t    *packet_ctx = (fr_dns_ctx_t *) decode_ctx;
   503
   504          FR_PROTO_TRACE("%s called to parse %zu byte(s)", __FUNCTION__, data_len);
   505
   506          if (data_len == 0) return 0;
   507
   508          /*
   509           *      This function is only used for testing, so update decode_ctx
   510           */
   511          packet_ctx->packet = data;
   512          packet_ctx->packet_len = data_len;
   513
   514          FR_PROTO_HEX_DUMP(data, data_len, NULL);
   515
   516          /*
   517           *      There should be at least room for the RR header
   518           */
   519          if (data_len < 9) {
   520                  fr_strerror_printf("%s: Insufficient data", __FUNCTION__);
   521                  return -1;
   522          }
   523
   524          slen = fr_struct_from_network(ctx, cursor, attr_dns_rr, data, data_len, true,
   525                                        decode_ctx, decode_value_trampoline, NULL);
   526          if (slen < 0) return slen;
   527
   528          FR_PROTO_TRACE("decoding option complete, returning %zd byte(s)", slen);
   529          return slen;
   530  }
